  (* [comment removed for export] *)
  Lemma accessible_readw_sr : forall m a w, accessible m a w -> 1 <= w -> a mod 8 + w <= 8 ->
    exists v, 0 <= v < 8 /\ (v = 0 \/ a mod 8 + w <= v)
      /\ ov_read_bytes asegs m (Z_to_bv 64 (Z.shiftr a 3 + 2147450880)) 1 = Some [b8 v].
  Proof.
    intros m a w AC Hw Hg. destruct (accessible_readw m a w AC Hw Hg) as (v & V1 & V2 & RD). exists v. split; [exact V1|]. split; [exact V2|].
    pose proof AC as (A0 & _ & _). unfold wa in RD. rewrite <- (sh_shiftr a), ASHADOW_BASE_val in RD by lia. exact RD.
  Qed.

  (* [comment removed for export] *)
  Lemma sxb_b8_small : forall v, 0 <= v < 128 -> sxb (b8 v) = Z_to_bv 64 v.
  Proof. intros v Hv. unfold sxb. rewrite b8_signed_small by lia. reflexivity. Qed.
  Lemma zxb_b8_small : forall v, 0 <= v < 256 -> zxb (b8 v) = Z_to_bv 64 v.
  Proof. intros v Hv. unfold zxb. rewrite b8_unsigned_small by lia. reflexivity. Qed.

  (* [comment removed for export] *)
  Lemma slow_arm_taken : forall a w v, 0 <= a -> 1 <= w -> 0 <= v < 8 -> a mod 8 + w <= v ->
