Lemma stk_transport_cov : forall W m m' lo hi A cs,
  stk asegs m lo hi -> munch W m m' -> wmono asegs m m' -> rw_cells asegs m' A cs ->
  (forall x, lo <= x < hi -> outside W x \/ (A <= x < A + Z.of_nat (cells_size cs))) -> stk asegs m' lo hi.
Proof.
  intros W m m' lo hi A cs ST MU WM RW COV. pose proof (stk_of_rw_cells asegs _ _ _ RW) as SC.
  destruct ST as (H1 & H2 & HS). destruct SC as (_ & _ & C).
  split; [lia|]. split; [lia|]. intros a Ha. destruct (COV a Ha) as [O|IN].
  - destruct (HS a Ha) as [Hw (b & Hb)]. split; [apply WM; exact Hw|]. exists b. unfold mrd in *. rewrite MU; [exact Hb|].
    rewrite wa_unsigned by lia. exact O.
  - apply C. lia.
Qed.

Lemma shvis_transport_cov : forall W m m' lo hi A cs,
  shvis m lo hi -> munch W m m' -> wmono asegs m m' -> rw_cells asegs m' A cs ->
  (forall x, sh (hull_lo lo) <= x < sh (hull_hi hi) -> outside W x \/ (A <= x < A + Z.of_nat (cells_size cs))) -> shvis m' lo hi.
Proof. intros W m m' lo hi A cs SV MU WM RW COV. unfold shvis in *. eapply stk_transport_cov; eauto. Qed.

