  (* [comment removed for export] *)
  Definition awin_fr (ff k : Z) (iv : Z * Z) : Prop :=
    awin iv \/ (Z.shiftr ff 3 + 2147450880 <= fst iv /\ snd iv <= Z.shiftr ff 3 + 2147450880 + fshn k).

  Lemma awin_fr_cov : forall W ff k x, Forall (awin_fr ff k) W -> 0 <= ff -> ALOWSH_LO < x < AHI_LO ->
    outside W x \/ (Z.shiftr ff 3 + 2147450880 <= x < Z.shiftr ff 3 + 2147450880 + fshn k).
  Proof.
    induction W as [|[l h] W IH]; intros ff k x FW Hff Hx; cbn [fst snd]; [left; exact I|].
    pose proof (Forall_inv FW) as K. destruct (IH ff k x (Forall_inv_tail FW) Hff Hx) as [O|IN]; [| right; exact IN].
    destruct K as [(_ & _ & K)|[K1 K2]]; cbn [fst snd] in *; [left; split; [lia| exact O]|].
    destruct (Z.lt_ge_cases x (Z.shiftr ff 3 + 2147450880)); [left; split; [lia| exact O]|].
    destruct (Z.lt_ge_cases x (Z.shiftr ff 3 + 2147450880 + fshn k)); [right; lia| left; split; [lia| exact O]].
  Qed.

  Lemma aside_transport_fr : forall W m m' lo shi ACC SHV ff k cs,
    aside m lo shi ACC SHV -> munch W m m' -> wmono asegs m m' ->
    0 <= k -> AIMG_TOP <= ff -> ff mod 8 = 0 -> ff + fsz k <= aceil ->
    Forall (awin_fr ff k) W ->
    Forall (fun o : Z * Z => fst o + snd o <= ff \/ ff + fsz k <= fst o) ACC ->
    rw_cells asegs m' (Z.shiftr ff 3 + 2147450880) cs -> Z.of_nat (cells_size cs) = fshn k ->
    aside m' lo shi ACC SHV.
