(* [comment removed for export] *)
Lemma rw_cells_CB0 : forall m m' A j, rw_cells asegs m A [CB 0 j] -> rw_cells asegs m' A [CB 0 j].
Proof.
  intros m m' A j [[WF (B1 & B2 & B3)] (W1 & W2 & W3)]. cbn in WF. destruct WF as [L _]. destruct j; [| cbn in L; lia].
  split; [split; [cbn; auto| split; [exact B1| split; [exact B2| intros i Hi; cbn in Hi; lia]]] | split; [exact W1| split; [exact W2| intros i Hi; cbn in Hi; lia]]].
Qed.
Lemma bytes_at_nil : forall m m' A, bytes_at asegs m A [] -> bytes_at asegs m' A [].
Proof. intros m m' A (B1 & B2 & B3). split; [exact B1| split; [exact B2| intros i Hi; cbn in Hi; lia]]. Qed.

Section FS.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.
  Hypothesis HH : asan_rt_hyps H.

  (* [comment removed for export] *)
  Lemma fs_pre_call : forall LF m m1 lo shi W,
    as_RFS H LF m -> athr_cells m -> ACONST m -> stack0 m lo shi ->
    munch W m m1 -> wmono asegs m m1 -> Forall (fun iv : Z * Z => aceil <= fst iv) W ->
    as_RFS H LF m1 /\ athr_cells m1 /\ ACONST m1 /\ stack0 m1 lo shi.
  Proof.
    intros LF m m1 lo shi W RF ATH AC SK MU WM FW. pose proof aceil_facts as (AF & _).
    pose proof (RFS_fsb _ HH _ _ RF) as (B1 & B2 & B3 & B4).
    split; [| split; [| split]].
    - eapply (ah_RFS_frame _ HH); [exact RF| exact MU| exact WM|]. eapply Forall_impl; [| exact FW].
      intros [l h] K. cbn in K. left. cbn [fst snd]. unfold ATLS_PRIV_LO, ATLS_PRIV_HI, ATP, AFS_SIZE in *. lia.
    - eapply athr_cells_frame; [exact ATH| exact MU| exact WM| exact FW].
    - eapply ACONST_frame; [exact AC| exact MU| exact WM|]. eapply Forall_impl; [| exact FW]. intros [l h] K. apply aconst_ok_hi. cbn [fst snd] in *. unfold AHI_LO. lia.
    - eapply stack0_transport; [exact SK| exact MU| exact WM|]. eapply Forall_impl; [| exact FW]. intros [l h] K. apply stack0_ok_app. cbn [fst snd] in *. unfold AHI_LO. lia.
  Qed.

  (* [comment removed for export] *)
  Definition fs_W5 (slo shi' fp ff k : Z) : list (Z * Z) :=
    [(slo, shi'); (as_FSB H, as_FSB H + AFS_FLAGS); (fp, fp + 1); (ff, ff + fsz k); (sh ff, sh ff + fshn k)]%Z.

