(* [comment removed for export] *)
Ltac hyde_disj := repeat match goal with K : _ \/ _ |- _ => hydeL K end.

(* [comment removed for export] *)
Ltac dj_subject :=
  lazymatch goal with
  | |- (?a + _ <= _ \/ _) /\ _ => a
  | |- ?a + _ <= _ \/ _ => a
  end.
Ltac dj_reveal_for a :=
  repeat match goal with K : hideL ?T |- _ => lazymatch T with context [a] => unfold hideL in K end end.
Ltac dj_lia :=
  first [ lia
        | let a := dj_subject in progress (dj_reveal_for a); lia
        | match goal with K : hideL _ |- _ => unfold hideL in K; lia end ].

(* [comment removed for export] *)
Tactic Notation "callZc" uconstr(SPEC) tactic3(CLR) :=
  lazymatch goal with
  | |- evt ?segs _ (MS _ _ _ _ _ ?m _) => eapply evt_cut; [ eapply SPEC | CLR; post_callZ segs m ]
  end.

(* [comment removed for export] *)
Ltac dj_seed H T :=
  lazymatch type of T with rw_cells _ _ ?A ?csT =>
    let S := dj_size_cells csT in
    let go A2 s2 := (let DJ := fresh "DJs" in assert (DJ : chunk_disj A2 s2 A S); [unfold chunk_disj|]) in
    lazymatch type of H with
    | rw_cells _ _ ?A2 ?cs2 => let s2 := dj_size_cells cs2 in go A2 s2
    | ro_cells _ _ ?A2 ?cs2 => let s2 := dj_size_cells cs2 in go A2 s2
    | bytes_at _ _ ?A2 ?bs2 => let s2 := dj_size_len (Z.of_nat (length bs2)) bs2 in go A2 s2
    | u8arr _ _ ?A2 ?bs2 => let s2 := dj_size_len (Z.of_nat (length bs2)) bs2 in go A2 s2
    | u8ro _ _ ?A2 ?bs2 => let s2 := dj_size_len (Z.of_nat (length bs2)) bs2 in go A2 s2
    end
  end.

(* [comment removed for export] *)
Tactic Notation "tr_keep" hyp(H) "over" hyp(MU) hyp(WM) "by" tactic3(tac) :=
  lazymatch type of MU with munch ?W ?m ?m' =>
  lazymatch type of H with
  | rw_cells _ _ ?A ?cs => apply (rw_cells_transport asegs W m m' A cs) in H; [| exact MU| exact WM| cbn [disjoint_from fst snd cells_size csize Nat.add]; tac]
  | ro_cells _ _ ?A ?cs => apply (ro_cells_transport asegs W m m' A cs) in H; [| exact MU| cbn [disjoint_from fst snd cells_size csize Nat.add]; tac]
  | bytes_at _ _ ?A ?bs => apply (bytes_at_transport asegs W m m' A bs) in H; [| exact MU| cbn [disjoint_from fst snd]; tac]
  | u8arr _ _ ?A ?bs => apply (u8arr_transport asegs W m m' A bs) in H; [| exact MU| exact WM| cbn [disjoint_from fst snd]; tac]
  | stk _ _ ?l ?h => apply (stk_transport_disjoint asegs W m m' l h) in H; [| exact MU| exact WM| cbn [disjoint_from fst snd]; tac]
  end end.

(* [comment removed for export] *)
Lemma munch_extend : forall W6 Wc (m0 m m' : mem),
  munch W6 m0 m -> munch Wc m m' -> sub_fp Wc W6 -> munch W6 m0 m'.
Proof. intros W6 Wc m0 m m' A B S. eapply munch_trans; [exact A| eapply munch_weaken; [exact S| exact B]]. Qed.

(* [comment removed for export] *)
Ltac fs_malloc_post HH :=
  let ms' := fresh "ms'" in let POST := fresh "POST" in
  intros ms' POST;
  let m2 := fresh "m2" in let ff := fresh "ff" in let fp := fresh "fp" in let hj1 := fresh "hj1" in let hj2 := fresh "hj2" in
  let E := fresh "E" in
  destruct POST as (?t0' & ?t1' & ?t2' & ?a1' & ?a2' & ?a3' & ?a4' & ?a5' & ?a6' & ?a7' & ?t3' & ?t4' & ?t5' & ?t6' & m2 & ff & fp & hj1 & hj2
                    & E & ?MUc & ?WMc & ?MIc & ?STc & ?RFc & ?FRM & ?SHc & ?FLc & ?ACc); subst ms';
  lazymatch goal with
  | MUc : munch _ _ m2, STc : stk _ m2 _ _, RFc : as_RFS _ _ m2 |- evt _ _ (MS _ _ (ret_pc (Z_to_bv 64 ?n)) _ _ _ _) =>
      rewrite ?unsigned_lit in MUc by lia; rewrite ?unsigned_lit in STc by lia;
      replace (ret_pc (Z_to_bv 64 n)) with (Z_to_bv 64 n) by (symmetry; apply ret_pc_even; [lia| reflexivity]);
      let FF := fresh "FF" in pose proof (fresh_of_RFS _ HH _ _ _ _ _ RFc) as FF
  end.
Tactic Notation "fs_malloc_call" constr(FS) constr(HH) :=
  let F := fresh "FS_" in pose proof FS as F; unfold stack_malloc_stmt, stack_malloc_post in F;
  eapply evt_cut; [eapply F | clear F; fs_malloc_post HH ].
